},
{
["recordedBy"] = "Simon-Windseeker",
["typeInfo"] = {
["player"] = {
["name"] = "Tirisfal Farmhand",
},
["event"] = "CHAT_MSG_MONSTER_EMOTE",
["type"] = "MONSTER_EMOTE",
},
["color"] = {
["r"] = 1,
["g"] = 0.501960813999176,
["b"] = 0.250980406999588,
},
["text"] = "Tirisfal Farmhand attempts to run away in fear!",
["timestamp"] = 1794009743,
["id"] = "s0_679",
},
{
["recordedBy"] = "Simon-Windseeker",
["typeInfo"] = {
["player"] = {
["name"] = "Bareth Dawnstone",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Bareth Dawnstone says: I can make it the rest of the way on my own. Let Shari Stilwell know I'm safe. I have one small matter to attend to first.",
["timestamp"] = 1794009757,
["id"] = "s0_680",
},
{
["recordedBy"] = "Simon-Windseeker",
["typeInfo"] = {
["player"] = {
["name"] = "Scarlet Warrior",
},
["event"] = "CHAT_MSG_MONSTER_EMOTE",
["type"] = "MONSTER_EMOTE",
},
["color"] = {
["r"] = 1,
["g"] = 0.501960813999176,
["b"] = 0.250980406999588,
},
["text"] = "Scarlet Warrior attempts to run away in fear!",
["timestamp"] = 1794009802,
["id"] = "s0_681",
},
{
["recordedBy"] = "Simon-Windseeker",
["typeInfo"] = {
["player"] = {
["name"] = "Leonid Barthalomew the Revered",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Leonid Barthalomew the Revered says: It's good to see you again, Danitha. It's only been a few years, but it feels like an ocean of time has passed.",
["timestamp"] = 1794009923,
["id"] = "s0_682",
},
{
["recordedBy"] = "Simon-Windseeker",
["typeInfo"] = {
["player"] = {
["name"] = "Danitha Morr",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Danitha Morr says: Indeed it does, Leonid. I've enjoyed our correspondence, but it pleases me that you finally made the trip out to Bandarion Keep in person.",
["timestamp"] = 1794009929,
["id"] = "s0_683",
},
{
["recordedBy"] = "Simon-Windseeker",
["typeInfo"] = {
["player"] = {
["race"] = "Scourge",
["name"] = "Simon Windseeker",
["sex"] = 3,
["class"] = "PALADIN",
["level"] = 11,
},
["event"] = "CHAT_MSG_LOOT",
["type"] = "LOOT",
},
["color"] = {
["r"] = -0,
["g"] = 0.6666666865348816,
["b"] = -0,
},
["text"] = "You receive item: |cnIQ1:|Hitem:282065::::::::11:1486:::::::::|h[Sealed Letter]|h|r",
["timestamp"] = 1794009931,
["id"] = "s0_684",
},
{
["recordedBy"] = "Simon-Windseeker",
["typeInfo"] = {
["player"] = {
["name"] = "Leonid Barthalomew the Revered",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Leonid Barthalomew the Revered says: I am glad I came to see what you've built here. Garek would be proud. This was no social call, though, Danitha. Surely you know that...",
["timestamp"] = 1794009936,
["id"] = "s0_685",
},
{
["recordedBy"] = "Simon-Windseeker",
["typeInfo"] = {
["player"] = {
["name"] = "Danitha Morr",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Danitha Morr says: Ah, so we are cutting straight to the point, then?",
["timestamp"] = 1794009943,
["id"] = "s0_686",
},
{
["recordedBy"] = "Simon-Windseeker",
["typeInfo"] = {
["player"] = {
["name"] = "Leonid Barthalomew the Revered",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Leonid Barthalomew the Revered says: Yes. Have you considered Lord Tyrosus's offer? The Argent Dawn is prepared to welcome you and your people with open arms.",
["timestamp"] = 1794009945,
["id"] = "s0_687",
},
{
["recordedBy"] = "Simon-Windseeker",
["typeInfo"] = {
["player"] = {
["name"] = "Danitha Morr",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Danitha Morr says: I'm sorry, Leonid, but I must decline. Much has changed but the Forsaken are still the people we swore to protect.",
["timestamp"] = 1794009952,
["id"] = "s0_688",
},
{
["recordedBy"] = "Simon-Windseeker",
["typeInfo"] = {
["player"] = {
["name"] = "Leonid Barthalomew the Revered",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Leonid Barthalomew the Revered says: But they fear and hate you, Danitha. Surely you know that? Among the Argent Dawn your connection to the light would be an asset. You would be highly valued!",
["timestamp"] = 1794009959,
["id"] = "s0_689",
},
{
["recordedBy"] = "Simon-Windseeker",
["typeInfo"] = {
["player"] = {
["name"] = "Danitha Morr",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Danitha Morr says: No, Leonid. Our place is here. Our fledgling order must find our identity amongst our kind. I know how you feel about the Forsaken... that our 'condition' is something to be cured.",
["timestamp"] = 1794009968,
["id"] = "s0_690",
},
{
["recordedBy"] = "Simon-Windseeker",
["typeInfo"] = {
["player"] = {
["name"] = "Danitha Morr",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Danitha Morr says: I reject that notion. This is who we are now, and we will make the Forsaken see that we are not what they think we are. We can be of service to Lordaeron again.",
["timestamp"] = 1794009984,
["id"] = "s0_691",
},
{
["recordedBy"] = "Simon-Windseeker",
["typeInfo"] = {
["player"] = {
["name"] = "Leonid Barthalomew the Revered",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Leonid Barthalomew the Revered says: Very well, Danitha. Just take care of yourselves. Many Forsaken cannot let go of the pain they suffered at the hands of the living wielders of the light. Their mistrust of paladins runs deep.",
["timestamp"] = 1794009986,
["id"] = "s0_692",
},
{
["recordedBy"] = "Simon-Windseeker",
["typeInfo"] = {
["player"] = {
["name"] = "Danitha Morr",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Danitha Morr says: That is why it is so important that we stay.",
["timestamp"] = 1794009996,
["id"] = "s0_693",
},
{
["recordedBy"] = "Simon-Windseeker",
["typeInfo"] = {
["player"] = {
["name"] = "Danitha Morr",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Danitha Morr says: Enough of this talk. I want to speak of the good times. Garek would have wanted that for us.",
["timestamp"] = 1794009999,
["id"] = "s0_694",
},
{
["recordedBy"] = "Simon-Windseeker",
["typeInfo"] = {
["event"] = "CHAT_MSG_MONEY",
["type"] = "MONEY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = -0,
},
["text"] = "You loot 3 Copper",
["timestamp"] = 1794010165,
["id"] = "s0_695",
},
